package export_test

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	dbml "github.com/aidenappl/go-dbml"
	"github.com/aidenappl/go-dbml/export"
)

// exportThreshold gates the per-dialect exact-match rate against the
// @dbml/core 10.3.1 goldens in testdata/export/<dialect>/ (generated by
// scripts/reference/export.mjs).
const exportThreshold = 0.95

// knownExportFailures lists goldens allowed to differ (dialect/set/name ->
// reason); anything else failing is a regression.
var knownExportFailures = map[string]string{
	// model metadata is a Go map: key order inside Metadata blocks is
	// sorted, @dbml/core keeps source order.
	"dbml/docs/enrichment_visualization_008": "metadata key order",
	"dbml/fixtures/metadata.in":              "metadata key order",
	"dbml/hand3/custom_props3":               "metadata key order",
	// safety: the reference prints a numeric column's non-numeric record
	// value (and a non-hex binary value) raw into the INSERT; go-dbml quotes
	// it as a string literal so record text can never become SQL.
	"mysql/examples/interpreter__record__type_compatibility_0180":    rawRecordValue,
	"mysql/examples/interpreter__record__type_compatibility_0200":    rawRecordValue,
	"postgres/examples/interpreter__record__type_compatibility_0180": rawRecordValue,
	"postgres/examples/interpreter__record__type_compatibility_0200": rawRecordValue,
	"mssql/examples/interpreter__record__type_compatibility_0180":    rawRecordValue,
	"mssql/examples/interpreter__record__type_compatibility_0200":    rawRecordValue,
	"mssql/hand4/x04_records":                                        rawRecordValue,
	// safety: a type containing "--" would comment out the rest of the
	// line; go-dbml refuses it (ErrUnsafeExpression).
	"mysql/core/normalized_model__schema_def.in":    unsafeType,
	"mysql/fixtures/negative_number.in":             unsafeType,
	"postgres/core/normalized_model__schema_def.in": unsafeType,
	"postgres/fixtures/negative_number.in":          unsafeType,
	"mssql/core/normalized_model__schema_def.in":    unsafeType,
	"mssql/fixtures/negative_number.in":             unsafeType,
	// safety: a PostgreSQL string value containing a backslash is written
	// E'...' so it reads the same with standard_conforming_strings off.
	"postgres/hand4/x04_records": "backslash string value written as E'...'",
}

const unsafeType = "type int(--1) contains a comment; refused as unsafe"

// documentedDeviations rewrites a reference output into what go-dbml
// emits for two systematic, documented deviations, so each one does not
// count as a failure in every golden it touches (the raw exact rate is
// logged too):
//   - mysql: a foreign key from a table in a named schema to a table in
//     the default schema is a prepared statement qualifying the referenced
//     table with DATABASE() (the reference leaves it unqualified, which
//     MySQL resolves in the wrong database);
//   - mssql: sp_addextendedproperty values and level names are N'...'
//     literals (Unicode-safe); index columns are [x], not "x" (a string
//     literal under QUOTED_IDENTIFIER OFF, sqlcmd's default);
//   - postgres: a parameterised or multi-word built-in type such as
//     "VARCHAR(20)" or "character varying(255)" is not quoted as an
//     identifier (the quoted form is invalid SQL).
func documentedDeviations(d export.Dialect, s string) string {
	switch d {
	case export.MySQL:
		return myCrossDB.ReplaceAllStringFunc(s, func(l string) string {
			m := myCrossDB.FindStringSubmatch(l)
			lit := func(x string) string {
				return "'" + strings.ReplaceAll(strings.ReplaceAll(x, "\\", "\\\\"), "'", "''") + "'"
			}
			return "SET @dbml_stmt = CONCAT(" + lit(m[1]+"REFERENCES `") + ", REPLACE(DATABASE(), '`', '``'), " + lit("`."+m[2]+m[3]) + ");\nPREPARE dbml_stmt FROM @dbml_stmt;\nEXECUTE dbml_stmt;\nDEALLOCATE PREPARE dbml_stmt;"
		})
	case export.MSSQL:
		s = msIndexLine.ReplaceAllStringFunc(s, func(l string) string {
			// only top-level column names of the column list
			open := strings.LastIndex(l[:strings.Index(l, " ON ")+4], " ON ")
			var b strings.Builder
			depth := 0
			for i := 0; i < len(l); i++ {
				c := l[i]
				switch {
				case i > open && c == '(':
					depth++
				case i > open && c == ')':
					depth--
				case i > open && c == '"' && depth == 1:
					m := msDQ.FindString(l[i:])
					n := strings.ReplaceAll(m[1:len(m)-1], `""`, `"`)
					b.WriteString("[" + strings.ReplaceAll(n, "]", "]]") + "]")
					i += len(m) - 1
					continue
				case c == '"' || c == '[':
					// skip quoted names before the column list
					if m := msDQ.FindString(l[i:]); c == '"' && m != "" {
						b.WriteString(m)
						i += len(m) - 1
						continue
					}
				}
				b.WriteByte(c)
			}
			return b.String()
		})
		return msNLit.ReplaceAllString(s, "$1 = N'")
	case export.Postgres:
		return pgColType.ReplaceAllStringFunc(s, func(m string) string {
			sub := pgColType.FindStringSubmatch(m)
			if strings.ContainsAny(sub[2], "(") || strings.Contains(sub[2], " ") || strings.HasSuffix(sub[2], "]") || strings.ToUpper(sub[2]) == sub[2] {
				if export.PgUnquotedBuiltin(sub[2]) {
					return sub[1] + sub[2]
				}
			}
			return m
		})
	}
	return s
}

var (
	// a FK from a table in a named schema (database) to a default-schema
	// table: go-dbml qualifies the referenced table with DATABASE()
	myCrossDB   = regexp.MustCompile("(?m)^(ALTER TABLE `[^`]*`\\.`[^`]*` ADD .*?)REFERENCES (`[^`]*`)( \\(.*);$")
	msNLit      = regexp.MustCompile(`(@value|@level[012]name) = '`)
	msIndexLine = regexp.MustCompile(`(?m)^CREATE (UNIQUE )?INDEX .* ON .*$`)
	msDQ        = regexp.MustCompile(`"(?:[^"]|"")*"`)
	pgColType   = regexp.MustCompile(`(?m)(^  "(?:[^"]|"")*" )"([^"]+)"`)
)

const rawRecordValue = "non-numeric record value in a numeric/binary column is quoted (reference emits it raw)"

// normalize trims trailing whitespace on every line and at the end.
func normalize(s string) string {
	lines := strings.Split(strings.ReplaceAll(s, "\r\n", "\n"), "\n")
	for i, l := range lines {
		lines[i] = strings.TrimRight(l, " \t")
	}
	return strings.TrimRight(strings.Join(lines, "\n"), "\n")
}

func inputPath(set, name string) string {
	if set == "holistics" {
		d, n, _ := strings.Cut(name, "__")
		return filepath.Join("../testdata/holistics/dbml-core/exporter", d, "input", n+".in.dbml")
	}
	return filepath.Join("../testdata/reference", set, name+".dbml")
}

func TestExportGoldens(t *testing.T) {
	for _, d := range append(append([]export.Dialect{}, export.Dialects...), "dbml") {
		t.Run(string(d), func(t *testing.T) {
			var files []string
			_ = filepath.WalkDir(filepath.Join("../testdata/export", string(d)), func(p string, e os.DirEntry, err error) error {
				if err == nil && !e.IsDir() && (strings.HasSuffix(p, ".sql") || strings.HasSuffix(p, ".err")) {
					files = append(files, p)
				}
				return nil
			})
			sort.Strings(files)
			if len(files) < 500 {
				t.Fatalf("only %d goldens for %s", len(files), d)
			}
			pass, raw := 0, 0
			var fails, regressions []string
			for _, gp := range files {
				set := filepath.Base(filepath.Dir(gp))
				ext := filepath.Ext(gp)
				name := strings.TrimSuffix(filepath.Base(gp), ext)
				src, err := os.ReadFile(inputPath(set, name))
				if err != nil {
					t.Fatal(err)
				}
				want, _ := os.ReadFile(gp)
				db, diags := dbml.Parse(string(src))
				id := fmt.Sprintf("%s/%s/%s", d, set, name)
				ok, why := false, ""
				if db == nil {
					why = fmt.Sprintf("does not compile: %v", diags)
				} else {
					var got string
					var err error
					if d == "dbml" {
						got, err = export.CoreDBML(db, export.CoreDBMLOptions{})
					} else {
						got, err = export.SQL(db, d)
					}
					switch {
					case ext == ".err":
						ok = err != nil && errors.Is(err, export.ErrModel)
						why = fmt.Sprintf("want error %q, got %v", strings.TrimSpace(string(want)), err)
					case err != nil:
						why = "unexpected error: " + err.Error()
					default:
						if normalize(got) == normalize(string(want)) {
							raw++
						}
						dev := documentedDeviations(d, string(want))
						ok = normalize(got) == normalize(dev)
						if !ok {
							why = firstLineDiff(normalize(dev), normalize(got))
						}
					}
				}
				if ok {
					pass++
					continue
				}
				fails = append(fails, id+": "+why)
				if _, known := knownExportFailures[id]; !known {
					regressions = append(regressions, id)
				}
			}
			rate := float64(pass) / float64(len(files))
			t.Logf("@dbml/core 10.3.1 %s exporter: %d/%d match modulo documented deviations (%.1f%%); %d/%d byte-exact", d, pass, len(files), rate*100, raw, len(files))
			for _, f := range fails {
				t.Logf("  FAIL %s", f)
			}
			if len(regressions) > 0 {
				t.Errorf("%d %s export golden(s) regressed (not in knownExportFailures)", len(regressions), d)
			}
			if rate < exportThreshold {
				t.Errorf("%s export match %.1f%% is below the %.0f%% gate", d, rate*100, exportThreshold*100)
			}
		})
	}
}

func firstLineDiff(want, got string) string {
	wl, gl := strings.Split(want, "\n"), strings.Split(got, "\n")
	for i := 0; i < len(wl) || i < len(gl); i++ {
		var w, g string
		if i < len(wl) {
			w = wl[i]
		}
		if i < len(gl) {
			g = gl[i]
		}
		if w != g {
			return fmt.Sprintf("line %d: want %q got %q", i+1, w, g)
		}
	}
	return "equal"
}

func TestParseDialect(t *testing.T) {
	for in, want := range map[string]export.Dialect{"MariaDB": export.MySQL, "postgresql": export.Postgres, "sqlserver": export.MSSQL} {
		if got, err := export.ParseDialect(in); err != nil || got != want {
			t.Errorf("ParseDialect(%q) = %v, %v", in, got, err)
		}
	}
	if _, err := export.ParseDialect("oracle"); err == nil {
		t.Error("oracle should be unsupported")
	}
}

func TestManyToManyJunction(t *testing.T) {
	db, _ := dbml.Parse("Table a { id int [pk] }\nTable b { id int [pk] }\nRef: a.id <> b.id\n")
	got, err := export.SQL(db, export.Postgres)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`CREATE TABLE "a_b" (`, `"a_id" int,`, `PRIMARY KEY ("a_id", "b_id")`,
		`ALTER TABLE "a_b" ADD FOREIGN KEY ("a_id") REFERENCES "a" ("id") DEFERRABLE INITIALLY IMMEDIATE;`} {
		if !strings.Contains(got, want) {
			t.Errorf("missing %q in\n%s", want, got)
		}
	}
}
